import SwiftUI
struct ActionBadgeView: View { let action: SwipeAction?; let onDismiss: ()->Void; @State private var visible=false; var body: some View { Group { if let action { capsule(action).scaleEffect(visible ? 1 : 0.6).opacity(visible ? 1 : 0) } }.onChange(of:action){_,newValue in if newValue != nil { show() }}.onAppear{ if action != nil { show() } } }
    private func capsule(_ action: SwipeAction)->some View { HStack(spacing:8){ icon(action); Text(action.badgeTitle).font(.system(size:12,weight:.medium)).foregroundStyle(DS.ColorToken.text) }.padding(.horizontal,14).padding(.vertical,9).background(Capsule().fill(DS.ColorToken.surface)).overlay(Capsule().stroke(DS.ColorToken.border,lineWidth:1)).shadow(color:.black.opacity(0.12),radius:8,x:0,y:4) }
    @ViewBuilder private func icon(_ action: SwipeAction)->some View { switch action { case .queue: Circle().fill(DS.ColorToken.primary).frame(width:8,height:8); case .priorityQueue: Image(systemName:"arrow.up.to.line.circle.fill").foregroundStyle(DS.ColorToken.primary); case .star: Image(systemName:"star.fill").foregroundStyle(DS.ColorToken.gold); case .dislike,.skip: Image(systemName:"minus.circle.fill").foregroundStyle(DS.ColorToken.textFaint) } }
    private func show(){ withAnimation(.badgeAppear){visible=true}; DispatchQueue.main.asyncAfter(deadline:.now()+2.5){withAnimation(.easeOut(duration:0.2)){visible=false}; DispatchQueue.main.asyncAfter(deadline:.now()+0.22){onDismiss()}} }
}
